<script>
 import {onMount} from 'svelte';import {apiRequest} from '../generation-client.js';import {ShieldCheck,RefreshCw} from 'lucide-svelte';
 let {admin=false}=$props();let data=$state(null),session=$state(null),wallet=$state(null),error=$state('');
 onMount(load);async function load(){try{session=await apiRequest('/session');wallet=await apiRequest('/wallet');if(admin)data=await apiRequest('/admin');}catch(e){error=e.message;}}
</script>
<div class="provider-page"><div class="page-heading"><div><div class="eyebrow">{admin?'ADMINISTRATOR ONLY':'SUBSCRIPTIONS & USAGE'}</div><h1>{admin?'AI Provider Settings':'Room for every ambition.'}</h1><p>{admin?'Secure server configuration. API credentials are never entered or displayed here.':'Subscription preview. Payments and real generation remain disabled.'}</p></div><button class="button secondary" onclick={load}><RefreshCw size={14}/> Refresh</button></div>
{#if error}<p class="director-error">{error}</p>{/if}
{#if admin&&data}<div class="provider-status-grid"><article class="surface"><ShieldCheck size={25}/><h2>{data.connectionStatus}</h2><p>Operating mode: <strong>{data.mode}</strong></p><p>API enabled: {data.apiEnabled?'Yes':'No'}</p><p>Key configured: {data.keyConfigured?'Yes':'No'}</p><p>Live verified: {data.liveVerified?'Yes':'No'}</p><p>Billing rules verified: {data.billingVerified?'Yes':'No'}</p></article><article class="surface"><h2>Activation checklist</h2><ol><li>Create and fund a Higgsfield API account when ready.</li><li>Store key ID and secret securely in the deployment environment.</li><li>Verify model schemas, reference support, output hosts, pricing and account access.</li><li>Run an explicitly authorized real test.</li><li>Enable Live Mode only after verification.</li></ol><p>Live Mode cannot be enabled from this browser.</p></article></div><section class="surface provider-audit"><h2>Generation usage</h2>{#each data.stats as s}<p>{s.mode} · {s.state} · {s.count} jobs</p>{/each}<h2>Provider error log</h2>{#if !data.errors.length}<p>No provider errors recorded.</p>{/if}{#each data.errors as e}<p>{new Date(e.created).toLocaleString()} · {e.code} · {e.message}</p>{/each}</section>{/if}
{#if wallet}<div class="credit-overview surface"><span>PREVIEW BALANCE · {wallet.period}</span><strong>{wallet.available}<small> credits available</small></strong><p>{wallet.held} reserved · {wallet.balance} total · No monetary value</p></div>{/if}{#if session}<div class="plan-grid">{#each Object.entries(session.plans) as [key,plan]}<article class="surface plan-card" class:featured={key==='pro'}><span>{key==='pro'?'CREATIVE FREEDOM':'PLAN PREVIEW'}</span><h2>{plan.name}</h2><strong>{plan.monthlyCredits.toLocaleString()} <small>credits / month</small></strong><p>{plan.price===null?'Pricing not activated':String(plan.price)} · configurable at launch</p><button class="button secondary" onclick={()=>error='Subscriptions are a preview. No payment processor is connected, and no purchase has been made.'}>{key==='free'?'Current preview plan':'Preview upgrade'}</button></article>{/each}</div><section class="surface provider-audit"><h2>Credit activity</h2><p>Only completed mock jobs consume preview credits. Cancellations release reservations. No real charges are made.</p>{#each wallet?.ledger||[] as entry}<div><span>{entry.event==='settled'?(entry.amount?'Demo usage':'Reservation released'):'Reservation'}</span><span>{entry.amount} · {entry.mode} · {new Date(entry.created).toLocaleString()}</span></div>{/each}</section>{/if}</div>
